mapper.select:
SELECT *
FROM transaction
WHERE client_id = #{clientId}
ORDER BY create_time;

SELECT *
    FROM transaction
WHERE client_id = #{clientId}
    AND currency = #{currency}
    AND YEAR(create_time) = #{year}
ORDER BY create_time DESC;

SELECT 'EUR' AS code
WHERE EXISTS (
    SELECT 1
    FROM transaction t
    WHERE t.client_id = #{clientId}
      AND t.currency = 'EUR'
)
UNION
SELECT 'USD' AS code
WHERE EXISTS (
    SELECT 1
    FROM transaction t
    WHERE t.client_id = #{clientId}
      AND t.currency = 'USD'
)
UNION
SELECT 'GBP' AS code
WHERE EXISTS (
    SELECT 1
    FROM transaction t
    WHERE t.client_id = #{clientId}
      AND t.currency = 'GBP'
);
